<?php
declare(strict_types=1);namespace App\Modules\SupplierPayments\Controllers;use App\Core\Exceptions\BusinessRuleException;use App\Core\Exceptions\ValidationException;use App\Core\Http\Csrf;use App\Core\Http\Request;use App\Core\Http\Response;use App\Core\Http\Session;use App\Core\View\View;use App\Modules\AccessControl\Services\AuthorizationService;use App\Modules\SupplierPayments\Services\SupplierPaymentService;use App\Modules\SupplierPayments\Validators\SupplierPaymentValidator;final class SupplierPaymentController{public function __construct(private readonly View$v,private readonly Csrf$csrf,private readonly Session$session,private readonly AuthorizationService$auth,private readonly SupplierPaymentService$s,private readonly SupplierPaymentValidator$validator){}public function index(Request$r):Response{return Response::html($this->v->render('modules/supplier-payments/index',['title'=>'مدفوعات الموردين','references'=>$this->s->references(),'canCreate'=>$this->auth->can('supplier_payments.create')]));}public function create(Request$r):Response{return$this->form(null,(int)$r->input('invoice_id'));}public function edit(Request$r):Response{$p=$this->s->find((int)$r->route('id'));return$this->form($p,0);}public function show(Request$r):Response{$p=$this->s->find((int)$r->route('id'));return Response::html($this->v->render('modules/supplier-payments/show',['title'=>'تفاصيل دفعة المورد','payment'=>$p,'summary'=>$this->s->summary((int)$p['supplier_invoice_id']),'canEdit'=>$this->auth->can('supplier_payments.edit'),'canPost'=>$this->auth->can('supplier_payments.post'),'canCancel'=>$this->auth->can('supplier_payments.cancel')]));}public function print(Request$r):Response{$p=$this->s->find((int)$r->route('id'));if($p['status']!=='posted')throw new BusinessRuleException('الطباعة متاحة للدفعات المرحلة فقط.');return Response::html($this->v->render('modules/supplier-payments/print',['title'=>'سند دفع مورد','payment'=>$p],'layouts/print'));}public function store(Request$r):Response{return$this->save($r,null);}public function update(Request$r):Response{return$this->save($r,(int)$r->route('id'));}public function post(Request$r):Response{return$this->action($r,'post');}public function cancel(Request$r):Response{return$this->action($r,'cancel');}private function form(?array$p,int$selected):Response{if($p&&$p['status']!=='draft')throw new BusinessRuleException('الدفعة غير قابلة للتعديل.');return Response::html($this->v->render('modules/supplier-payments/form',['title'=>$p?'تعديل مسودة دفعة':'إضافة دفعة مورد','payment'=>$p,'selectedInvoice'=>$selected,'references'=>$this->s->references()]));}private function save(Request$r,?int$id):Response{if(!$this->csrf->isValid($r->input('_token')))return Response::html('انتهت صلاحية الطلب.',419);try{$id=$this->s->save($this->validator->validate($r->all()),$id);$this->flash('success','تم الحفظ','تم حفظ مسودة الدفعة.');return Response::redirect('/supplier-payments/'.$id);}catch(ValidationException|BusinessRuleException$e){$m=$e instanceof ValidationException?(string)reset($e->errors[array_key_first($e->errors)]):$e->getMessage();$this->flash('error','تعذر الحفظ',$m);return Response::redirect($id?'/supplier-payments/'.$id.'/edit':'/supplier-payments/create');}}private function action(Request$r,string$a):Response{if(!$this->csrf->isValid($r->input('_token')))return Response::html('انتهت صلاحية الطلب.',419);$id=(int)$r->route('id');try{$a==='post'?$this->s->post($id):$this->s->cancel($id);$this->flash('success','تم التحديث',$a==='post'?'تم ترحيل الدفعة.':'تم إلغاء المسودة.');}catch(BusinessRuleException$e){$this->flash('error','تعذر التحديث',$e->getMessage());}return Response::redirect('/supplier-payments/'.$id);}private function flash(string$t,string$h,string$x):void{$this->session->flash('alert',['type'=>$t,'title'=>$h,'text'=>$x]);}}
